module gem_collector(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] r,\n    input [15:0] w,\n    input [15:0] h,\n    input [15:0] x_0,\n    input [15:0] x_1,\n    input [15:0] x_2,\n    input [15:0] x_3,\n    input [15:0] x_4,\n    input [15:0] x_5,\n    input [15:0] x_6,\n    input [15:0] x_7,\n    input [15:0] x_8,\n    input [15:0] x_9,\n    input [15:0] x_10,\n    input [15:0] x_11,\n    input [15:0] x_12,\n    input [15:0] x_13,\n    input [15:0] x_14,\n    input [15:0] x_15,\n    input [15:0] y_0,\n    input [15:0] y_1,\n    input [15:0] y_2,\n    input [15:0] y_3,\n    input [15:0] y_4,\n    input [15:0] y_5,\n    input [15:0] y_6,\n    input [15:0] y_7,\n    input [15:0] y_8,\n    input [15:0] y_9,\n    input [15:0] y_10,\n    input [15:0] y_11,\n    input [15:0] y_12,\n    input [15:0] y_13,\n    input [15:0] y_14,\n    input [15:0] y_15,\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE      = 3'd0;\n    localparam [2:0] SORT      = 3'd1;\n    localparam [2:0] DP_INIT   = 3'd2;\n    localparam [2:0] DP_LOOP   = 3'd3;\n    localparam [2:0] FIND_MAX  = 3'd4;\n    localparam [2:0] DONE_ST   = 3'd5;\n\n    reg [2:0] state, next_state;\n\n    // Arrays\n    reg [15:0] sorted_x [0:15];\n    reg [15:0] sorted_y [0:15];\n    reg [7:0] dp [0:15];\n\n    // Counters\n    reg [3:0] k;\n    reg [3:0] j_iter;\n    reg [3:0] i;\n    reg [3:0] j_dp;\n    reg [3:0] max_index;\n    reg [7:0] current_max;\n\n    // Temporaries\n    reg [15:0] x_diff;\n    reg [15:0] y_diff;\n    reg [19:0] product;\n    reg swap_flag;\n    reg [15:0] temp_y;\n    reg [15:0] temp_x;\n\n    // Cycle counter\n    reg [7:0] cycle_count;\n\n    integer idx;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            done <= 1'b0;\n            result <= 8'd0;\n            cycle_count <= 8'd0;\n            k <= 4'd0;\n            j_iter <= 4'd0;\n            i <= 4'd0;\n            j_dp <= 4'd0;\n            max_index <= 4'd0;\n            current_max <= 8'd0;\n            x_diff <= 16'd0;\n            y_diff <= 16'd0;\n            product <= 20'd0;\n            swap_flag <= 1'b0;\n            for (idx = 0; idx < 16; idx = idx + 1) begin\n                sorted_x[idx] <= 16'd0;\n                sorted_y[idx] <= 16'd0;\n                dp[idx] <= 8'd0;\n            end\n            state <= IDLE;\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 8'd0;\n                    if (start) begin\n                        // Load input arrays\n                        sorted_x[0] <= x_0;  sorted_y[0] <= y_0;\n                        sorted_x[1] <= x_1;  sorted_y[1] <= y_1;\n                        sorted_x[2] <= x_2;  sorted_y[2] <= y_2;\n                        sorted_x[3] <= x_3;  sorted_y[3] <= y_3;\n                        sorted_x[4] <= x_4;  sorted_y[4] <= y_4;\n                        sorted_x[5] <= x_5;  sorted_y[5] <= y_5;\n                        sorted_x[6] <= x_6;  sorted_y[6] <= y_6;\n                        sorted_x[7] <= x_7;  sorted_y[7] <= y_7;\n                        sorted_x[8] <= x_8;  sorted_y[8] <= y_8;\n                        sorted_x[9] <= x_9;  sorted_y[9] <= y_9;\n                        sorted_x[10] <= x_10; sorted_y[10] <= y_10;\n                        sorted_x[11] <= x_11; sorted_y[11] <= y_11;\n                        sorted_x[12] <= x_12; sorted_y[12] <= y_12;\n                        sorted_x[13] <= x_13; sorted_y[13] <= y_13;\n                        sorted_x[14] <= x_14; sorted_y[14] <= y_14;\n                        sorted_x[15] <= x_15; sorted_y[15] <= y_15;\n                        next_state <= SORT;\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n\n                SORT: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (cycle_count >= 8'd200) begin\n                        next_state <= FIND_MAX;\n                    end else if (k < n - 4'd1) begin\n                        if (j_iter < n - k - 4'd1) begin\n                            temp_y = sorted_y[j_iter];\n                            temp_x = sorted_x[j_iter];\n                            if (sorted_y[j_iter] > sorted_y[j_iter + 4'd1]) begin\n                                // Swap elements\n                                sorted_y[j_iter] <= sorted_y[j_iter + 4'd1];\n                                sorted_x[j_iter] <= sorted_x[j_iter + 4'd1];\n                                sorted_y[j_iter + 4'd1] <= temp_y;\n                                sorted_x[j_iter + 4'd1] <= temp_x;\n                                swap_flag <= 1'b1;\n                            end\n                            j_iter <= j_iter + 4'd1;\n                            next_state <= SORT;\n                        end else begin\n                            j_iter <= 4'd0;\n                            k <= k + 4'd1;\n                            next_state <= SORT;\n                        end\n                    end else begin\n                        k <= 4'd0;\n                        j_iter <= 4'd0;\n                        next_state <= DP_INIT;\n                    end\n                end\n\n                DP_INIT: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (cycle_count >= 8'd200) begin\n                        next_state <= FIND_MAX;\n                    end else begin\n                        for (idx = 0; idx < 16; idx = idx + 1) begin\n                            dp[idx] <= (idx < n) ? 8'd1 : 8'd0;\n                        end\n                        i <= 4'd1;\n                        j_dp <= 4'd0;\n                        next_state <= DP_LOOP;\n                    end\n                end\n\n                DP_LOOP: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (cycle_count >= 8'd200) begin\n                        next_state <= FIND_MAX;\n                    end else if (i < n) begin\n                        if (j_dp < i) begin\n                            // Calculate x_diff\n                            x_diff <= (sorted_x[j_dp] > sorted_x[i]) ? (sorted_x[j_dp] - sorted_x[i]) : (sorted_x[i] - sorted_x[j_dp]);\n                            // Calculate y_diff\n                            y_diff <= sorted_y[i] - sorted_y[j_dp];\n                            // Multiply r * x_diff\n                            product <= r * x_diff;\n                            // Check condition\n                            if (y_diff >= product && dp[j_dp] + 8'd1 > dp[i]) begin\n                                dp[i] <= dp[j_dp] + 8'd1;\n                            end\n                            j_dp <= j_dp + 4'd1;\n                            next_state <= DP_LOOP;\n                        end else begin\n                            j_dp <= 4'd0;\n                            i <= i + 4'd1;\n                            next_state <= DP_LOOP;\n                        end\n                    end else begin\n                        next_state <= FIND_MAX;\n                    end\n                end\n\n                FIND_MAX: begin\n                    cycle_count <= cycle_count + 8'd1;\n                    if (max_index < n) begin\n                        if (dp[max_index] > current_max) begin\n                            current_max <= dp[max_index];\n                        end\n                        max_index <= max_index + 4'd1;\n                        next_state <= FIND_MAX;\n                    end else begin\n                        result <= current_max;\n                        next_state <= DONE_ST;\n                    end\n                end\n\n                DONE_ST: begin\n                    result <= current_max;\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\n\n    // Next state logic (combinational)\n    always @(*) begin\n        next_state = state;\n    end\n\nendmodule